#include "lib/std.mi"

//bad apple - high quality version (you need a supercomputer to run this at 100% speed)

Global Text mainText, mainText2, mainText3, mainText4;
Global Timer mainTimer;

Global int frameNumber, frameCount, frameSize;
Global double frameRate;

Global List frameList;

Function loadBadApple();
Function String decompressRLE(String in);

System.onScriptLoaded() {
  //xml stuff
  Group scriptgroup = getScriptGroup();
  mainText = scriptgroup.getObject("badapple_text");
  mainText2 = scriptgroup.getObject("badapple_text2");
  mainText3 = scriptgroup.getObject("badapple_text3");
  mainText4 = scriptgroup.getObject("badapple_text4");

  //create lists
  frameList = new List;

  //add frames to list
  loadBadApple();

  //how many strings are used to build a frame
  frameSize = 13;

  //frame count is length of frameList
  frameCount = frameList.getNumItems();

  frameRate = 33.3;

  //update timer
  mainTimer = new Timer;
  mainTimer.setDelay(33);

  if(frameCount % frameSize != 0) mainText.setXmlParam("text", "framecount("+integerToString(frameCount)+") is not a divisor of frameSize("+integerToString(frameSize)+")!\nThis might crash Winamp!");
  else mainText.setXmlParam("text", "Bad Apple!! in Winamp demo by mirzi (2021)\n...press play");
}

System.onPlay(){
  mainTimer.start();
  mainText.setXmlParam("fontsize", "7");
}

System.onResume(){
  mainTimer.start();
  mainText.setXmlParam("fontsize", "7");
}

System.onStop(){
  mainTimer.stop();
}

System.onPause(){
  mainTimer.stop();
}

mainTimer.onTimer(){
  //get correct frame number with modulo
  int frameNum = (frameSize*frameNumber)%frameCount;

  //combine strings into one
  String frame1 = "";
  String frame2 = "";
  String frame3 = "";
  String frame4 = "";
  for(int i = 0; i<4; i++){
    frame1 += decompressRLE( frameList.enumItem(frameNum+i) );
    frame2 += decompressRLE( frameList.enumItem(4+frameNum+i) );
    frame3 += decompressRLE( frameList.enumItem(8+frameNum+i) );
  }

  frame4 = decompressRLE( frameList.enumItem(frameNum+12) );

  //display frame
  mainText.setXmlParam("text", frame1);
  mainText2.setXmlParam("text", frame2);
  mainText3.setXmlParam("text", frame3);
  mainText4.setXmlParam("text", frame4);
  
  frameNumber = System.integer(System.getPosition() / frameRate);
}

//simple RLE decompression algorithm
decompressRLE(String in){
  String str = "";
  String buffer = "";
  String newline ="
";

  for (int i = 0; i < strlen(in); i++){
    String char = strmid(in, i, 1);
    if (char == "a"){
      int count = stringToInteger(buffer);
      for(int o = 0; o < count; o++){
        str+="█";
      }
      buffer = "";
    } else if (char == "b"){
      int count = stringToInteger(buffer);
      for(int o = 0; o < count; o++){
        str+=" ";
      }
      buffer = "";
    } else if (char == ","){
      str+=newline;
    } else buffer += char;
  }

  return str;
}

